  "bootswatch/cerulean/_bootswatch.scss": "// Cerulean 5.1.3\n// Bootswatch\n\n\n// Variables\n\n$text-shadow: 0 1px 0 rgba(0, 0, 0, .05) !default;\n\n// Mixins\n\n@mixin btn-shadow($color){\n  @include gradient-y-three-colors(tint-color($color, 16%), $color, 60%, shade-color($color, 6%));\n}\n\n// Navbar\n\n.navbar {\n  @each $color, $value in $theme-colors {\n    &.bg-#{$color} {\n      @include btn-shadow($value);\n    }\n  }\n}\n\n.navbar-brand,\n.nav-link {\n  text-shadow: $text-shadow;\n}\n\n// Buttons\n\n.btn {\n  text-shadow: $text-shadow;\n}\n\n.btn-secondary {\n  color: $gray-700;\n}\n\n@each $color, $value in $theme-colors {\n  .btn-#{$color} {\n    @include btn-shadow($value);\n  }\n}\n\n// Typography\n\n.text-secondary {\n  color: $gray-500 !important;\n}\n\n.bg-primary,\n.bg-success,\n.bg-info,\n.bg-warning,\n.bg-danger,\n.bg-dark {\n  h1,\n  h2,\n  h3,\n  h4,\n  h5,\n  h6 {\n    color: $white;\n  }\n}\n\n// Navs\n\n.dropdown-menu {\n  .dropdown-header {\n    color: $gray-600;\n  }\n}\n\n// Indicators\n\n.badge {\n  &.bg-secondary,\n  &.bg-light {\n    color: $dark;\n  }\n}\n",
  "bootswatch/cerulean/_variables.scss": "// Cerulean 5.1.3\n// Bootswatch\n\n$theme: \"cerulean\" !default;\n\n//\n// Color system\n//\n\n$white:    #fff !default;\n$gray-100: #f8f9fa !default;\n$gray-200: #e9ecef !default;\n$gray-300: #dee2e6 !default;\n$gray-400: #ced4da !default;\n$gray-500: #adb5bd !default;\n$gray-600: #868e96 !default;\n$gray-700: #495057 !default;\n$gray-800: #343a40 !default;\n$gray-900: #212529 !default;\n$black:    #000 !default;\n\n$blue:    #033c73 !default;\n$indigo:  #6610f2 !default;\n$purple:  #6f42c1 !default;\n$pink:    #e83e8c !default;\n$red:     #c71c22 !default;\n$orange:  #fd7e14 !default;\n$yellow:  #dd5600 !default;\n$green:   #73a839 !default;\n$teal:    #20c997 !default;\n$cyan:    #2fa4e7 !default;\n\n$primary:       $cyan !default;\n$secondary:     $gray-200 !default;\n$success:       $green !default;\n$info:          $blue !default;\n$warning:       $yellow !default;\n$danger:        $red !default;\n$light:         $gray-100 !default;\n$dark:          $gray-800 !default;\n\n$min-contrast-ratio:   2.75 !default;\n\n// Body\n\n$body-color:    $gray-700 !default;\n\n// Fonts\n\n$headings-color:         $cyan !default;\n\n// Dropdowns\n\n$dropdown-link-color:           $body-color !default;\n$dropdown-link-hover-color:     $white !default;\n$dropdown-link-hover-bg:        $primary !default;\n\n// Navbar\n\n$navbar-dark-color:             rgba($white, .8) !default;\n$navbar-dark-hover-color:       $white !default;\n",
  "bootswatch/cosmo/_bootswatch.scss": "// Cosmo 5.1.3\n// Bootswatch\n\n\n// Variables\n\n$web-font-path: \"https://fonts.googleapis.com/css2?family=Source+Sans+Pro:wght@300;400;700&display=swap\" !default;\n@if $web-font-path {\n  @import url($web-font-path);\n}\n\n// Typography\n\nbody {\n  -webkit-font-smoothing: antialiased;\n}\n\n// Indicators\n\n.badge {\n  &.bg-light {\n    color: $dark;\n  }\n}\n\n// Progress bars\n\n.progress {\n  @include box-shadow(none);\n\n  .progress-bar {\n    font-size: 8px;\n    line-height: 8px;\n  }\n}\n",
