  "mod-style-assets/card-mod-bootstrap/assets/style/bootstrap_colorpicker.scss": "/*!\n * Bootstrap Colorpicker v2.5.2\n * https://itsjavi.com/bootstrap-colorpicker/\n *\n * Originally written by (c) 2012 Stefan Petre\n * Licensed under the Apache License v2.0\n * http://www.apache.org/licenses/LICENSE-2.0.txt\n *\n */\n\n@mixin bgImg($imgBase64) {\n  background-image: url(\"#{$imgBase64}\");\n}\n\n@mixin borderRadius($size) {\n  -webkit-border-radius: $size;\n  -moz-border-radius: $size;\n  border-radius: $size;\n}\n\n.colorpicker-saturation {\n  width: 100px;\n  height: 100px;\n  @include bgImg('data:image/png;base64,');\n  cursor: crosshair;\n  float: left;\n  i {\n    display: block;\n    height: 5px;\n    width: 5px;\n    border: 1px solid #000;\n    @include borderRadius(5px);\n    position: absolute;\n    top: 0;\n    left: 0;\n    margin: -4px 0 0 -4px;\n    b {\n      display: block;\n      height: 5px;\n      width: 5px;\n      border: 1px solid #fff;\n      @include borderRadius(5px);\n    }\n  }\n}\n\n.colorpicker-hue,\n.colorpicker-alpha {\n  width: 15px;\n  height: 100px;\n  float: left;\n  cursor: row-resize;\n  margin-left: 4px;\n  margin-bottom: 4px;\n}\n\n.colorpicker-hue i,\n.colorpicker-alpha i {\n  display: block;\n  height: 1px;\n  background: #000;\n  border-top: 1px solid #fff;\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  margin-top: -1px;\n}\n\n.colorpicker-hue {\n  @include bgImg('data:image/png;base64,');\n}\n\n.colorpicker-alpha {\n  @include bgImg('data:image/png;base64,');\n  display: none;\n}\n\n.colorpicker-saturation,\n.colorpicker-hue,\n.colorpicker-alpha {\n  background-size: contain;\n}\n\n.colorpicker {\n  padding: 4px;\n  min-width: 130px;\n  margin-top: 1px;\n  @include borderRadius(4px);\n  z-index: 2500;\n}\n\n.colorpicker:before,\n.colorpicker:after {\n  display: table;\n  content: \"\";\n  line-height: 0;\n}\n\n.colorpicker:after {\n  clear: both;\n}\n\n.colorpicker:before {\n  content: '';\n  display: inline-block;\n  border-left: 7px solid transparent;\n  border-right: 7px solid transparent;\n  border-bottom: 7px solid #ccc;\n  border-bottom-color: rgba(0, 0, 0, 0.2);\n  position: absolute;\n  top: -7px;\n  left: 6px;\n}\n\n.colorpicker:after {\n  content: '';\n  display: inline-block;\n  border-left: 6px solid transparent;\n  border-right: 6px solid transparent;\n  border-bottom: 6px solid $white;\n  position: absolute;\n  top: -6px;\n  left: 7px;\n}\n\n.colorpicker div {\n  position: relative;\n}\n\n.colorpicker.colorpicker-with-alpha {\n  min-width: 140px;\n}\n\n.colorpicker.colorpicker-with-alpha .colorpicker-alpha {\n  display: block;\n}\n\n.colorpicker-color {\n  height: 10px;\n  margin-top: 5px;\n  clear: both;\n  @include bgImg('data:image/png;base64,');\n  background-position: 0 100%;\n}\n\n.colorpicker-color div {\n  height: 10px;\n}\n\n.colorpicker-selectors {\n  display: none;\n  height: 10px;\n  margin-top: 5px;\n  clear: both;\n}\n\n.colorpicker-selectors i {\n  cursor: pointer;\n  float: left;\n  height: 10px;\n  width: 10px;\n}\n\n.colorpicker-selectors i + i {\n  margin-left: 3px;\n}\n\n.colorpicker-element .input-group-addon i,\n.colorpicker-element .add-on i {\n  display: inline-block;\n  cursor: pointer;\n  height: 16px;\n  vertical-align: text-top;\n  width: 16px;\n}\n\n.colorpicker.colorpicker-inline {\n  position: relative;\n  display: inline-block;\n  float: none;\n  z-index: auto;\n}\n\n.colorpicker.colorpicker-horizontal {\n  width: 110px;\n  min-width: 110px;\n  height: auto;\n}\n\n.colorpicker.colorpicker-horizontal .colorpicker-saturation {\n  margin-bottom: 4px;\n}\n\n.colorpicker.colorpicker-horizontal .colorpicker-color {\n  width: 100px;\n}\n\n.colorpicker.colorpicker-horizontal .colorpicker-hue,\n.colorpicker.colorpicker-horizontal .colorpicker-alpha {\n  width: 100px;\n  height: 15px;\n  float: left;\n  cursor: col-resize;\n  margin-left: 0px;\n  margin-bottom: 4px;\n}\n\n.colorpicker.colorpicker-horizontal .colorpicker-hue i,\n.colorpicker.colorpicker-horizontal .colorpicker-alpha i {\n  display: block;\n  height: 15px;\n  background: $white;\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 1px;\n  border: none;\n  margin-top: 0px;\n}\n\n.colorpicker.colorpicker-horizontal .colorpicker-hue {\n  @include bgImg('data:image/png;base64,');\n}\n\n.colorpicker.colorpicker-horizontal .colorpicker-alpha {\n  @include bgImg('data:image/png;base64,');\n}\n\n.colorpicker-right:before {\n  left: auto;\n  right: 6px;\n}\n\n.colorpicker-right:after {\n  left: auto;\n  right: 7px;\n}\n\n.colorpicker-no-arrow:before {\n  border-right: 0;\n  border-left: 0;\n}\n\n.colorpicker-no-arrow:after {\n  border-right: 0;\n  border-left: 0;\n}\n\n.colorpicker,\n.colorpicker-alpha,\n.colorpicker-saturation,\n.colorpicker-hue,\n.colorpicker-selectors {\n  &.colorpicker-visible {\n    display: block;\n  }\n}\n\n.colorpicker,\n.colorpicker-alpha,\n.colorpicker-saturation,\n.colorpicker-hue,\n.colorpicker-selectors {\n  &.colorpicker-hidden {\n    display: none;\n  }\n}\n\n.colorpicker-inline.colorpicker-visible {\n  display: inline-block;\n}\n",
  "mod-style-assets/card-mod-bootstrap/assets/style/decko_bootstrap.scss": "//.select2-container--bootstrap .select2-search-box-autocomplete.select2-selection--multiple {\n//  .select2-selection__choice {\n//    background: none !important;\n//    border: none !important;\n//  }\n//\n//  .select2-selection__choice__remove {\n//    display: none !important;\n//  }\n//}\n\n.badge {\n  vertical-align: text-top !important;\n}\n\n.dropdown-menu {\n  z-index: 1005;\n}\n\n.select2-dropdown a {\n  text-decoration: none !important;\n}\n",
